-- Step 4: clean up the ingestion backlog and staging once rows are promoted.
BEGIN;
DELETE FROM ingestion_backlog b
WHERE EXISTS (SELECT 1 FROM products p WHERE p.match_key = b.match_key);

DELETE FROM staging_products sp
WHERE EXISTS (SELECT 1 FROM products p WHERE p.brand = sp.brand AND p.match_key = sp.match_key);
COMMIT;
